def transform(grid):
    out = [row[:] for row in grid]
    points = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 2]
    rows = {}
    cols = {}
    for r, c in points:
        rows.setdefault(r, []).append(c)
        cols.setdefault(c, []).append(r)
    shared_rows = [(r, cs) for r, cs in rows.items() if len(cs) >= 2]
    shared_cols = [(c, rs) for c, rs in cols.items() if len(rs) >= 2]
    if shared_rows:
        r0, cs = max(shared_rows, key=lambda item: len(item[1]))
        lo, hi = min(cs), max(cs)
        for c in range(lo, hi + 1):
            if out[r0][c] == 0:
                out[r0][c] = 3
        for r, c in points:
            if r != r0:
                for rr in range(min(r, r0), max(r, r0) + 1):
                    if out[rr][c] == 0:
                        out[rr][c] = 3
    elif shared_cols:
        c0, rs = max(shared_cols, key=lambda item: len(item[1]))
        lo, hi = min(rs), max(rs)
        for r in range(lo, hi + 1):
            if out[r][c0] == 0:
                out[r][c0] = 3
        for r, c in points:
            if c != c0:
                for cc in range(min(c, c0), max(c, c0) + 1):
                    if out[r][cc] == 0:
                        out[r][cc] = 3
    return out
